        answer: 'Mi ara tilint tiwaɣitin ur nṣeḥḥ ara, isnaw zemren ad beddlen s waṭas. AWA tesseqdac amazray-ik udmawan war ma tḥessib s wudem awurman tawaɣit tameqqrant d tǧehhel.'
